function vibrateFX(kind='message'){if(!state.vibration||!navigator.vibrate)return;const patterns={notification:[35],whatsapp:[35,45,35],instagram:[25,35,65],call:[80,90,80,90,180],unknown:[160,70,35]};try{navigator.vibrate(patterns[kind]||patterns.notification)}catch(e){}}function playFX(kind='notification'){if(!state.sound)return;try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const c=new A(),g=c.createGain();g.gain.value=.045;g.connect(c.destination);const seq=kind==='instagram'?[880,1174]:kind==='whatsapp'?[659,880]:kind==='sent'?[520]:kind==='unknown'?[146,110,146]:[740,880];let t=c.currentTime;seq.forEach((hz,i)=>{const o=c.createOscillator(),v=c.createGain();o.type=kind==='unknown'?'triangle':'sine';o.frequency.value=hz;v.gain.setValueAtTime(.0001,t);v.gain.exponentialRampToValueAtTime(.7,t+.018);v.gain.exponentialRampToValueAtTime(.0001,t+.14);o.connect(v);v.connect(g);o.start(t);o.stop(t+.16);t+=(kind==='unknown' ? 0.19 : 0.12)});c.resume().then(()=>setTimeout(()=>c.close(),900))}catch(e){}}
function renderNotificationCenter(){const list=$('notificationList'),empty=$('ncEmpty');if(!list)return;list.innerHTML=notificationHistory.slice(0,20).map((n,i)=>'<button class="nc-item" data-notification="'+i+'"><span class="mini-app" style="background:'+(appList.find(x=>x[0]===n.app)?.[1]||'#555')+'">'+icon(n.app)+'</span><span><b>'+escapeHTML(n.title)+'</b><small>'+escapeHTML(n.message)+'</small></span><time>'+escapeHTML(n.time)+'</time></button>').join('');if(empty)empty.classList.toggle('hidden',notificationHistory.length>0);list.querySelectorAll('[data-notification]').forEach(btn=>btn.onclick=()=>{const n=notificationHistory[+btn.dataset.notification];$('notificationCenter').classList.add('hidden');openApp(n.app||'Messages')})}
