function renderMission(){const n=Math.min(state.mission,4),done=state.mission;$('missionCount').textContent=done+'/5';$('missionBar').style.width=(done*20)+'%';$('missionName').textContent=done>=5?'ALL CLUES FOUND':('MISSION 0'+(n+1)+' · '+missionData[n][0]);$('missionHint').textContent=done>=5?'The final recording is waiting.':missionData[n][1];if($('missionWidget'))$('missionWidget').onclick=()=>openApp('Notes')}
function completeMission(key){const idx={wa:0,dm:1,photo:2,note:3,voice:4}[key];if(idx===undefined||state.done.includes(key))return;state.done.push(key);while(state.mission<5&&state.done.includes(['wa','dm','photo','note','voice'][state.mission]))state.mission++;save();if(state.mission>idx)banner('MISSION COMPLETE',missionData[idx][0]+' · '+(missionData[state.mission]?.[1]||'Final clue unlocked.'),'Messages');if(key==='wa')setTimeout(()=>banner('Instagram','@notjames sent you a message request.','Instagram',()=>openApp('Instagram')),1800);if(key==='dm')setTimeout(()=>banner('Photos','James, check the photo from 22:47.','Photos',()=>openApp('Photos')),1300);if(state.mission===5){setTimeout(()=>banner('FINAL MISSION','The last recording is ready.','Voice Memos'),900)}}
