let gestureStart=null;let recentApps=[];function showAppSwitcher(){let panel=$('appSwitcher');if(!panel){panel=document.createElement('section');panel.id='appSwitcher';panel.className='app-switcher hidden';$('screen').appendChild(panel)}panel.innerHTML='<div class="switcher-title">Recently Opened</div><div class="switcher-cards">'+(recentApps.length?recentApps.map(n=>'<button data-switch-app="'+escapeHTML(n)+'"><b>'+escapeHTML(n)+'</b><span>Tap to return</span></button>').join(''):'<p>No recent apps</p>')+'</div><button class="switcher-home" type="button">Home Screen</button>';panel.classList.remove('hidden');panel.querySelectorAll('[data-switch-app]').forEach(x=>x.onclick=()=>{panel.classList.add('hidden');openApp(x.dataset.switchApp)});panel.querySelector('.switcher-home').onclick=()=>{panel.classList.add('hidden');showView('home')}}$('screen').addEventListener('touchstart',e=>{if(e.touches.length===1)gestureStart={x:e.touches[0].clientX,y:e.touches[0].clientY,target:e.target,at:Date.now()}},{passive:true});$('screen').addEventListener('touchend',e=>{if(!gestureStart)return;const dy=e.changedTouches[0].clientY-gestureStart.y,dx=e.changedTouches[0].clientX-gestureStart.x,fromTop=gestureStart.y<32,fromBottom=gestureStart.y>window.innerHeight-45,interactive=gestureStart.target.closest('input,textarea,button,.app-body,.chat-messages,.ig-stories,.photo-grid,.photo-detail,.story-overlay,.chat-options,.chat-compose');if(fromTop&&dy>85&&!interactive){if(gestureStart.x<window.innerWidth*.5){$('notificationCenter').classList.remove('hidden');renderNotificationCenter()}else $('controlCenter').classList.remove('hidden')}else if(fromBottom&&dy< -75&&!interactive){if(Date.now()-gestureStart.at>350)showAppSwitcher();else showView('home')}else if(!$('lock').classList.contains('hidden')&&dy< -85&&Math.abs(dx)<65)showView('passcode');gestureStart=null},{passive:true});$('closeCC').onclick=()=>$('controlCenter').classList.add('hidden');$('closeNC').onclick=()=>$('notificationCenter').classList.add('hidden');renderNotificationCenter();
