const koreanVoiceRecords=[{file:'voice_2211.m4a',time:'22:11',duration:'0:08',ko:'복도 끝에 누군가 서 있었어. 내 재킷을 입고 있었는데, 내가 이름을 불렀을 때 아무 소리도 내지 않았어.',id:'Ada seseorang berdiri di ujung lorong. Dia memakai jaketku, tetapi saat kupanggil namanya, dia tidak mengeluarkan suara.'},{file:'james_final.m4a',time:'23:08',duration:'0:14',ko:'내 목소리로 너희 이름을 부르는 소리를 따라가지 마. 그 애는 내 목소리는 흉내 낼 수 있어도, 우리의 기억까지는 흉내 내지 못해.',id:'Jangan ikuti suara yang memanggil nama kalian dengan suaraku. Dia bisa meniru suaraku, tetapi belum bisa meniru ingatan kita.'},{file:'untitled_03.m4a',time:'03:33',duration:'0:19',ko:'내 사진을 전부 봐 줘서 고마워. 이제 누구의 얼굴을 가져야 하는지 알겠어. 화면을 끄지 마. 아직 네가 필요해.',id:'Terima kasih sudah melihat semua fotoku. Sekarang aku tahu wajah siapa yang harus kupakai. Jangan matikan layar. Aku masih membutuhkanmu.'}];function renderVoice(b){b.innerHTML='<div class="section-caption">All recordings · Korean voice / Indonesian translation</div>'+koreanVoiceRecords.map((r,i)=>'<div class="voice-card"><strong>◉　'+r.file+'</strong><small>Recording · '+r.time+' · '+r.duration+' · James</small><div class="voice-wave">'+Array.from({length:34},(_,j)=>'<i style="height:'+((j*17+i*9)%27+4)+'px"></i>').join('')+'</div><button data-record="'+i+'">▶ Play Korean audio</button><div class="voice-transcript"><b>Terjemahan Indonesia</b><p>'+r.id+'</p><small class="voice-status" id="voiceStatus'+i+'">Menggunakan Korean speech synthesis jika suara ko-KR tersedia di perangkat.</small></div></div>').join('');b.querySelectorAll('[data-record]').forEach(btn=>btn.onclick=()=>{const i=+btn.dataset.record,r=koreanVoiceRecords[i],status=$('voiceStatus'+i);if(!('speechSynthesis'in window)){status.textContent='Perangkat ini tidak mendukung Korean speech synthesis. Audio belum tersedia.';return}speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(r.ko);utter.lang='ko-KR';utter.rate=.88;utter.pitch=.92;const korean=speechSynthesis.getVoices().find(v=>/^ko(-|_)/i.test(v.lang));if(korean)utter.voice=korean;else status.textContent='Suara ko-KR tidak ditemukan. Perangkat mungkin memakai suara pengganti.';utter.onstart=()=>{btn.textContent='Ⅱ Playing';status.textContent='Memutar audio bahasa Korea.'};utter.onend=()=>{btn.textContent='▶ Play Korean audio';status.textContent='Rekaman selesai.'};utter.onerror=()=>{btn.textContent='▶ Play Korean audio';status.textContent='Audio gagal diputar pada perangkat ini.'};speechSynthesis.speak(utter);if(i===2){completeMission('voice');setTimeout(showEnding,10500)}})}
let tlnAudioContext=null,tlnAudioNodes=[];
