function playJuhoonPOV(button){
  const status=button.parentElement.querySelector('.pov-audio-status')||button.nextElementSibling;
  const A=window.AudioContext||window.webkitAudioContext;
  if(!A){if(status)status.textContent='Audio tidak didukung perangkat ini.';return}
  stopTLNAudio();if(tlnAudioContext){try{tlnAudioContext.close()}catch(e){}}
  const ac=new A();tlnAudioContext=ac;ac.resume();button.disabled=true;button.textContent='Ⅱ Playing';if(status)status.textContent='Listen carefully… ada suara jauh di ujung lorong.';
  const master=ac.createGain();master.gain.value=.22;master.connect(ac.destination);
  const noiseBuffer=ac.createBuffer(1,ac.sampleRate*8,ac.sampleRate),data=noiseBuffer.getChannelData(0);
  for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.22;
  const noise=ac.createBufferSource();noise.buffer=noiseBuffer;
  const filter=ac.createBiquadFilter();filter.type='bandpass';filter.frequency.setValueAtTime(720,ac.currentTime);filter.frequency.linearRampToValueAtTime(1150,ac.currentTime+5.5);filter.Q.value=.7;
  const ng=ac.createGain();ng.gain.setValueAtTime(.001,ac.currentTime);ng.gain.linearRampToValueAtTime(.075,ac.currentTime+2.2);ng.gain.setValueAtTime(.055,ac.currentTime+4.7);ng.gain.linearRampToValueAtTime(.001,ac.currentTime+7.7);
  const pan=ac.createStereoPanner?ac.createStereoPanner():null;if(pan){pan.pan.setValueAtTime(-.65,ac.currentTime);pan.pan.linearRampToValueAtTime(.55,ac.currentTime+5.4);filter.connect(ng);ng.connect(pan);pan.connect(master)}else{filter.connect(ng);ng.connect(master)}
  noise.connect(filter);noise.start();noise.stop(ac.currentTime+7.9);tlnAudioNodes.push(noise);
  [0.9,2.8,5.2].forEach((at,i)=>{const o=ac.createOscillator(),g=ac.createGain(),p=ac.createStereoPanner?ac.createStereoPanner():null;o.type='sine';o.frequency.setValueAtTime(78-i*7,ac.currentTime+at);o.frequency.exponentialRampToValueAtTime(48,ac.currentTime+at+.65);g.gain.setValueAtTime(.001,ac.currentTime+at);g.gain.linearRampToValueAtTime(i===2?.13:.075,ac.currentTime+at+.08);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+at+.8);o.connect(g);if(p){p.pan.value=i===1?.55:-.35;g.connect(p);p.connect(master)}else g.connect(master);o.start(ac.currentTime+at);o.stop(ac.currentTime+at+.85);tlnAudioNodes.push(o)});
  const end=setTimeout(()=>{button.disabled=false;button.textContent='↻ Replay audio';if(status)status.textContent='Audio selesai. Saat diputar ulang, perhatikan suara yang muncul menjelang akhir.';ac.close().catch(()=>{});if(tlnAudioContext===ac)tlnAudioContext=null},8200);
  button.dataset.audioTimer=String(end);
}
