function renderSafari(b){b.innerHTML='<div class="safari-search">⌕　Search or enter website address</div><div class="section-caption">Recently searched</div>'+[['what is a doppelgänger','A double of a living person.'],['can reflections move independently','A reflection should follow the observer.'],['why is my face in a photo i never took','No matching search results.']].map(x=>'<div class="safari-result"><h3>'+x[0]+'</h3><p>'+x[1]+'</p></div>').join('')}
$('homeIndicator').addEventListener('dblclick',()=>showAppSwitcher());
$('lock').addEventListener('click',e=>{if(e.target.closest('.lock-notification'))showView('passcode')});
$('ending').addEventListener('click',e=>{if(e.target===$('ending'))toast('There is no way back from this notification.')});
renderMission();
if(state.unlocked){showView('home')}else{showView('lock');addLockNotification('WhatsApp · CORTIS','James: jangan buka gallery.','WhatsApp')}
if(state.ending)showEnding();